    "rsmdesignBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "jmvdoe",
                name = "rsmdesign",
                version = c(1,0,0),
                options = options,
                results = rsmdesignResults$new(options=options),
