#' Response Surface Design
#'
#' 
#' @param data .
#' @param factors .
#' @param designType .
#' @param alpha .
#' @param n0 .
#' @param replicates .
#' @param randomize .
#' @param seed .
#' @param responses .
#' @param responseTarget .
#' @param simulateResponses .
#' @param evaluateDesign .
#' @param analysisModel .
#' @param halfNormal .
#' @param pareto .
#' @param mainEffects .
#' @param interaction .
#' @param residuals .
#' @param contour .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$info} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$design} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$coded} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$analysisInfo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$analysisAnova} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$analysisCoef} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$analysisRecommend} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$analysisHalfNormal} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$analysisPareto} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$analysisMainEffects} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$analysisInteraction} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$analysisResiduals} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$analysisContour} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$design$asDF}
#'
#' \code{as.data.frame(results$design)}
#'
#' @export
rsmdesign <- function(
    data,
    factors = list(),
    designType = "ccd",
    alpha = "rotatable",
    n0 = 3,
    replicates = 1,
    randomize = TRUE,
    seed = 1,
    responses = list(),
    responseTarget = 0,
    simulateResponses = TRUE,
    evaluateDesign = FALSE,
    analysisModel = "rsm",
    halfNormal = TRUE,
    pareto = TRUE,
    mainEffects = FALSE,
    interaction = FALSE,
    residuals = TRUE,
    contour = TRUE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("rsmdesign requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- rsmdesignOptions$new(
        factors = factors,
        designType = designType,
        alpha = alpha,
        n0 = n0,
        replicates = replicates,
        randomize = randomize,
        seed = seed,
        responses = responses,
        responseTarget = responseTarget,
        simulateResponses = simulateResponses,
        evaluateDesign = evaluateDesign,
        analysisModel = analysisModel,
        halfNormal = halfNormal,
        pareto = pareto,
        mainEffects = mainEffects,
        interaction = interaction,
        residuals = residuals,
        contour = contour)

    analysis <- rsmdesignClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

